import {campaignBrowserPage,hallStageStatus,HALL_BROWSER_PAGE_SIZE} from './hall-campaign-browser-model.mjs';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
/** One controller per Hall. Input and selection state are never saved as progress. */
export function createHallCampaignBrowser({host}){
 let state={campaignId:null,regionId:null,query:'',page:0,regionPage:0,stageId:null},context=null;
 function render({focus=null,searchFocus=false}={}){
  if(!context)return;
  const {catalog,campaignId,activeDestination,onInspectCampaign,onInspectCharter,activeLevel}=context;
  if(state.campaignId!==campaignId){
   const entry=catalog.find(item=>item.id===campaignId),stages=entry?.regions.flatMap(r=>r.stages)??[],stage=(campaignId==='campaign'&&activeDestination===campaignId?stages.find(s=>Number(s.id)===activeLevel):null)??stages.find(s=>s.state==='frontier'||s.state==='current')??stages.findLast(s=>s.state==='cleared')??stages[0];
   const regionIndex=entry?.regions.findIndex(region=>region.id===stage?.regionId)??0,region=entry?.regions[Math.max(0,regionIndex)],stageIndex=region?.stages.findIndex(item=>item.id===stage?.id)??0;
   state={campaignId,regionId:stage?.regionId??null,query:'',page:Math.floor(Math.max(0,stageIndex)/HALL_BROWSER_PAGE_SIZE),regionPage:Math.floor(Math.max(0,regionIndex)/HALL_BROWSER_PAGE_SIZE),stageId:stage?.id??null};
  }
  const model=campaignBrowserPage(catalog,state);if(!model){host.innerHTML='';return;}
  state.page=model.page;state.regionPage=model.regionPage;state.regionId=model.region?.id??null;
  const {campaign,selected}=model,active=activeDestination===campaign.id;
  const selectedInResults=selected&&model.stages.some(stage=>stage.id===selected.id);
  if(!selectedInResults)state.stageId=model.stages[0]?.id??null;
  const inspected=selectedInResults?selected:model.stages[0]??null;
  const groupPaging=model.regionPageCount>1?`<div class="hall-directory-pager"><button type="button" data-hall-region-page="-1" ${model.regionPage===0?'disabled':''}>Previous ${campaign.groupLabel.toLowerCase()}</button><span>${model.regionPage+1} / ${model.regionPageCount}</span><button type="button" data-hall-region-page="1" ${model.regionPage===model.regionPageCount-1?'disabled':''}>Next ${campaign.groupLabel.toLowerCase()}</button></div>`:'';
  host.innerHTML=`<header class="hall-directory-head"><p>${escape(campaign.description)}</p><label for="hallStageSearch">Find a field in ${escape(campaign.name)}</label><div class="hall-directory-search"><input id="hallStageSearch" type="search" maxlength="120" value="${escape(state.query)}" placeholder="Field name, region or number" autocomplete="off"><button type="button" id="hallClearSearch" ${state.query?'':'disabled'}>Clear</button></div></header>
   <div class="hall-directory-layout"><nav class="hall-directory-regions" aria-label="${escape(campaign.name)} ${campaign.groupLabel.toLowerCase()}"><h3>${campaign.groupLabel}</h3>${model.regions.map(region=>`<button type="button" data-hall-browser-region="${escape(region.id)}" aria-pressed="${!state.query&&region.id===model.region?.id}" style="--hall-region-art:url('./images/regions/${escape(region.art??region.id)}.webp')"><strong>${escape(region.name)}</strong><span>${region.stages.length} ${region.stages.length===1?'field':'fields'} · ${region.stages.filter(s=>s.state==='cleared').length} ${campaign.assisted?'reached':'cleared'}</span></button>`).join('')}${groupPaging}</nav>
   <section class="hall-directory-fields" aria-label="Named campaign fields"><div class="hall-directory-breadcrumb">${escape(campaign.name)} <span aria-hidden="true">›</span> ${state.query?'Search results':escape(model.region?.name??'Fields')}</div><p id="hallBrowserResults" role="status">${model.matched?`${model.start}–${model.end} of ${model.matched} fields`:'No fields match your search.'}</p><div class="hall-field-list">${model.stages.map(stage=>`<button type="button" data-hall-stage="${escape(stage.id)}" data-state="${escape(stage.state)}" aria-pressed="${stage.id===inspected?.id}"><span class="hall-field-number">${stage.number}</span><span class="hall-field-identity"><strong>${escape(stage.name)}</strong><small>${escape(stage.regionName)} · ${hallStageStatus(stage.state,campaign.assisted)}${active&&campaign.id==='campaign'&&Number(stage.id)===activeLevel?' · Prepared field':''}</small></span><span aria-hidden="true" class="hall-field-marker">${stage.state==='cleared'?'✓':stage.state==='locked'?'◇':'›'}</span></button>`).join('')}</div><div class="hall-directory-pager"><button type="button" id="hallFieldsPrevious" ${model.page===0?'disabled':''}>Previous fields</button><span>Page ${model.page+1} of ${model.pageCount}</span><button type="button" id="hallFieldsNext" ${model.page===model.pageCount-1?'disabled':''}>Next fields</button></div></section></div>
   ${inspected?`<section class="hall-field-brief" aria-labelledby="hallFieldName"><span class="eyebrow">${campaign.stageLabel.toUpperCase()} ${inspected.number} · ${hallStageStatus(inspected.state,campaign.assisted)}</span><h3 id="hallFieldName">${escape(inspected.name)}</h3><p>${escape(inspected.objective)}</p><p>${escape(inspected.advice)}</p><button type="button" id="hallInspectField" ${active?'':'disabled'}>${campaign.id==='campaign'?'Inspect field in map':'Open charter routes'}</button><p class="hall-directory-note">${!active?'Open this campaign with the departure button below before preparing a field. Your active session stays unchanged while browsing.':campaign.id==='campaign'?'Inspection is read-only. The map applies the earned frontier and live-battle preparation rules.':'Choose the next road in the charter route after a settled victory. Browsing a field does not select a branch.'}</p></section>`:''}`;
  const query=host.querySelector('#hallStageSearch');
  query.oninput=()=>{const cursor=query.selectionStart;state.query=query.value.slice(0,120);state.page=0;state.stageId=null;render({searchFocus:true});const input=host.querySelector('#hallStageSearch');if(cursor!==null)input.setSelectionRange?.(cursor,cursor);};
  host.querySelector('#hallClearSearch').onclick=()=>{state.query='';state.page=0;state.stageId=null;render({searchFocus:true});};
  for(const button of host.querySelectorAll('[data-hall-browser-region]'))button.onclick=()=>{state.regionId=button.getAttribute('data-hall-browser-region');state.query='';state.page=0;state.stageId=null;render({focus:`[data-hall-browser-region="${state.regionId}"]`});};
  for(const button of host.querySelectorAll('[data-hall-stage]'))button.onclick=()=>{state.stageId=button.getAttribute('data-hall-stage');render({focus:`[data-hall-stage="${state.stageId}"]`});};
  for(const button of host.querySelectorAll('[data-hall-region-page]'))button.onclick=()=>{state.regionPage+=Number(button.getAttribute('data-hall-region-page'));render({focus:'[data-hall-browser-region]'});};
  const changePage=delta=>{state.page+=delta;state.stageId=null;render({focus:'[data-hall-stage]'});};
  host.querySelector('#hallFieldsPrevious').onclick=()=>changePage(-1);host.querySelector('#hallFieldsNext').onclick=()=>changePage(1);
  const inspect=host.querySelector('#hallInspectField');if(inspect)inspect.onclick=()=>{if(!active||!inspected)return;campaign.id==='campaign'?onInspectCampaign?.(Number(inspected.id)):onInspectCharter?.();};
  if(searchFocus)host.querySelector('#hallStageSearch')?.focus?.({preventScroll:true});else if(focus)host.querySelector(focus)?.focus?.({preventScroll:true});
 }
 return {sync(value){context=value;render();},get selection(){return {...state};}};
}
